{
  "root": "main",
  "state": {
    "itinerary": [
      {
        "day": "Day 1",
        "area": "Baixa, Rossio, Alfama",
        "morningActivity": "Arrival and hotel check-in",
        "afternoonActivity": "Walking tour of historic center",
        "dinnerSuggestion": "Alfama neighborhood dining",
        "icon": "../assets/r_004291_01_2_building.svg"
      },
      {
        "day": "Day 2",
        "area": "Graça and Mouraria",
        "morningActivity": "Museum visit",
        "afternoonActivity": "Walking tour and viewpoints",
        "dinnerSuggestion": "Free evening",
        "icon": "../assets/r_004318_01_1_book.svg"
      },
      {
        "day": "Day 3",
        "area": "Sintra",
        "morningActivity": "Pena Palace or Quinta da Regaleira",
        "afternoonActivity": "Monserrate gardens",
        "dinnerSuggestion": "Relaxed dinner near hotel",
        "icon": "../assets/r_004321_01_4_train-front.svg"
      },
      {
        "day": "Day 4",
        "area": "Belém",
        "morningActivity": "Jerónimos Monastery",
        "afternoonActivity": "Riverside walk and pastries",
        "dinnerSuggestion": "Final dinner",
        "icon": "../assets/r_004306_01_1_water.svg"
      }
    ],
    "budget": [
      { "item": "Hotel, 3 nights", "cost": "€450" },
      { "item": "Meals and coffee", "cost": "€320" },
      { "item": "Local transit", "cost": "€50" },
      { "item": "Museums and entry fees", "cost": "€140" },
      { "item": "Sintra day trip", "cost": "€96" },
      { "item": "Snacks, pastries, misc.", "cost": "€120" },
      { "item": "Buffer for upgrades", "cost": "€424" },
      { "item": "Total", "cost": "€1,600" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["header", "itineraryTable", "budgetTable", "actions"]
    },
    "header": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "align": "center" },
      "children": ["title"]
    },
    "title": {
      "type": "Text",
      "props": { "text": "Lisbon 4-Day Trip Plan", "variant": "h1" },
      "children": []
    },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "area", "label": "Area" },
          { "key": "morningActivity", "label": "Morning" },
          { "key": "afternoonActivity", "label": "Afternoon" },
          { "key": "dinnerSuggestion", "label": "Dinner" }
        ]
      },
      "children": []
    },
    "budgetTable": {
      "type": "Table",
      "props": {
        "statePath": "/budget",
        "domain": "generic",
        "preferredPresentation": "table",
        "columns": [
          { "key": "item", "label": "Item" },
          { "key": "cost", "label": "Estimated Cost" }
        ]
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3", "btn4"]
    },
    "btn1": { "type": "Button", "props": { "label": "Find Hotels", "openUrl": "https://www.booking.com/city/pt/lisbon.en-gb.html" }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Train to Sintra", "openUrl": "https://www.cp.pt/passageiros/en" }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Lisbon Museums", "openUrl": "https://www.visitlisboa.com/en/lisbon/museums" }, "children": [] },
    "btn4": { "type": "Button", "props": { "label": "Official Tourism", "openUrl": "https://www.visitlisboa.com/en" }, "children": [] }
  }
}
